                target_enemy = enemy_pos

    # Decide movement
    dx, dy = 0, 0

    # Pursue resource if available
    if target_resource:
        dx = 0
        dy = 0
        if target_resource[0] > position[0]:
            dx = 1
        elif target_resource[0] < position[0]:
            dx = -1
        # same for y
        if target_resource[1] > position[1]:
            dy = 1
        elif target_resource[1] < position[1]:
            dy = -1
        # Prioritize moving towards resource
        # If already at resource, stay still
        if position == target_resource:
            dx, dy = 0, 0
        else:
            # Move in the direction that reduces distance
            # Prefer horizontal or vertical based on larger difference
            delta_x = target_resource[0] - position[0]
            delta_y = target_resource[1] - position[1]
            if abs(delta_x) > abs(delta_y):
                dy = 0
            else:
