    # Else, pursue enemy
    elif target_enemy:
        dx = 0
        dy = 0
        if target_enemy[0] > position[0]:
            dx = 1
        elif target_enemy[0] < position[0]:
            dx = -1
        if target_enemy[1] > position[1]:
            dy = 1
        elif target_enemy[1] < position[1]:
            dy = -1
        # Move towards enemy
        if position == target_enemy:
            dx, dy = 0, 0
        else:
            delta_x = target_enemy[0] - position[0]
            delta_y = target_enemy[1] - position[1]
            if abs(delta_x) > abs(delta_y):
                dy = 0
            else:
                dx = 0

    # Else, default to stay still or random move to explore
    else:
        dx, dy = 0, 0

    # Clip to -1..1
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
    return [dx, dy]

